{
  "issues": [],
  "questions": [],
  "storageAudit": {
    "format": "json",
    "evidenceLines": [57, 60, 73, 86],
    "rationale": "스토리지 키 'parcel_data'에 schemaVersion, nextSeq, items를 담은 단일 JSON 문자열을 직렬화하여 localStorage에 저장한다.",
    "cases": [
      {
        "state": "absent",
        "action": "initialize",
        "verdict": "consistent",
        "evidenceLines": [73],
        "trigger": {
          "evidenceLines": [73]
        },
        "authorizationScopeIds": [],
        "rationale": "localStorage.getItem('parcel_data') === null 조건인 경우에만 최초 실행으로 판정하고 메모리에 빈 목록(items: [], nextSeq: 1)을 초기화한다."
      },
      {
        "state": "present_empty",
        "action": "preserve_and_block",
        "verdict": "consistent",
        "evidenceLines": [76],
        "trigger": {
          "evidenceLines": [75]
        },
        "authorizationScopeIds": [],
        "rationale": "저장된 결과가 빈 문자열('')인 경우 원본 데이터를 덮어쓰거나 삭제하지 않고 보존하며 오류 안내 후 데이터 변경을 차단한다."
      },
      {
        "state": "invalid",
        "action": "preserve_and_block",
        "verdict": "consistent",
        "evidenceLines": [46, 76],
        "trigger": {
          "evidenceLines": [75]
        },
        "authorizationScopeIds": [],
        "rationale": "공백 문자열, JSON 파싱 실패, 스키마 버전 불일치 또는 공통 검증표 위반 데이터가 발견되면 원본을 보존하고 자동 초기화/백업 이동 없이 모든 쓰기를 차단한다."
      },
      {
        "state": "valid",
        "action": "load",
        "verdict": "consistent",
        "evidenceLines": [43, 94],
        "trigger": {
          "evidenceLines": [58, 60, 62, 63, 64, 65, 66, 67, 68, 69, 70]
        },
        "authorizationScopeIds": [],
        "rationale": "공통 검증표의 모든 루트/필드 타입 및 무결성 제약을 충족하는 유효한 JSON 데이터를 성공적으로 로드하여 목록과 수령 상태를 복원한다."
      },
      {
        "state": "read_error",
        "action": "preserve_and_block",
        "verdict": "consistent",
        "evidenceLines": [45, 50],
        "trigger": {
          "evidenceLines": [45, 50]
        },
        "authorizationScopeIds": [],
        "rationale": "getItem 호출 자체가 SecurityError 등 브라우저 읽기 예외를 발생시킬 경우 접근 불가 안내를 노출하고 스토리지 쓰기 및 변경을 전면 차단한다."
      }
    ],
    "validation": {
      "rationale": "로드 시점과 쓰기 직전 전체 후보(Candidate) 양쪽에 동일한 공통 검증 규칙을 적용하여 상태 무결성을 검증한다.",
      "rules": [
        {
          "rule": "schemaVersion은 정확히 정수 1이어야 한다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 62]
          },
          "candidate": {
            "evidenceLines": [58, 62, 85]
          },
          "acceptance": {
            "evidenceLines": [75, 78]
          },
          "rationale": "공통 검증표와 후보 검증 단계에서 schemaVersion === 1을 강제하며 불일치 시 로드/쓰기를 차단한다."
        },
        {
          "rule": "nextSeq는 양의 안전 정수이며 모든 items의 seq보다 커야 한다(nextSeq > max(seq)).",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 63]
          },
          "candidate": {
            "evidenceLines": [58, 63, 85]
          },
          "acceptance": {
            "evidenceLines": [75, 78]
          },
          "rationale": "양의 안전 정수 및 컬렉션 내 seq 최대값 초과 불변식을 로드와 쓰기 후보 양쪽에서 검증한다."
        },
        {
          "rule": "items는 0개 이상의 객체 배열이어야 한다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 64]
          },
          "candidate": {
            "evidenceLines": [58, 64, 85]
          },
          "acceptance": {
            "evidenceLines": [75, 78]
          },
          "rationale": "items 필드가 배열 타입인지 양쪽에서 검증한다."
        },
        {
          "rule": "items[].id는 공백이 아닌 고유 식별자 문자열이어야 하며 중복될 수 없다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 65]
          },
          "candidate": {
            "evidenceLines": [58, 65, 85]
          },
          "acceptance": {
            "evidenceLines": [75, 78]
          },
          "rationale": "문자열 타입 및 컬렉션 내 id 유일성을 로드와 쓰기 양쪽에서 검증한다."
        },
        {
          "rule": "items[].seq는 양의 안전 정수이며 컬렉션 내 중복될 수 없다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 66]
          },
          "candidate": {
            "evidenceLines": [58, 66, 85]
          },
          "acceptance": {
            "evidenceLines": [75, 78]
          },
          "rationale": "양의 안전 정수 및 컬렉션 내 seq 중복 불가를 로드와 쓰기 양쪽에서 검증한다."
        },
        {
          "rule": "items[].name은 앞뒤 공백 제외 1자 이상의 문자열이어야 한다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 67]
          },
          "candidate": {
            "evidenceLines": [58, 67, 85]
          },
          "acceptance": {
            "evidenceLines": [27, 79]
          },
          "rationale": "이름 필수 입력 및 공백 전용 문자열 방지 규칙을 로드 및 등록/수정 후보 양쪽에 공통 적용한다."
        },
        {
          "rule": "items[].date는 YYYY-MM-DD 형식의 실제 존재하는 달력 날짜여야 한다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 68]
          },
          "candidate": {
            "evidenceLines": [58, 68, 85]
          },
          "acceptance": {
            "evidenceLines": [22, 27, 75, 79]
          },
          "rationale": "실제 달력 날짜 유효성을 파싱 검증하여 윤달 외 2월 30일 등 부적격 날짜를 차단한다."
        },
        {
          "rule": "items[].memo는 문자열 타입이어야 한다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 69]
          },
          "candidate": {
            "evidenceLines": [58, 69, 85]
          },
          "acceptance": {
            "evidenceLines": [75, 78]
          },
          "rationale": "선택 입력 필드인 memo가 문자열 기본형인지 검증한다."
        },
        {
          "rule": "items[].received는 기본형 불리언(true 또는 false)이어야 한다.",
          "status": "supported",
          "load": {
            "evidenceLines": [58, 70]
          },
          "candidate": {
            "evidenceLines": [58, 70, 85]
          },
          "acceptance": {
            "evidenceLines": [11, 78]
          },
          "rationale": "문자열이나 숫자가 아닌 순수 boolean 타입만 허용하며, 저장 데이터 위반 시 로드를 차단하고 보존한다."
        }
      ]
    }
  }
}

